SELECT male_patients_with_high_lab_instability.subject_id, male_patients_with_high_lab_instability.hadm_id, male_patients_with_high_lab_instability.admittime, male_patients_with_high_lab_instability.dischtime, male_patients_with_high_lab_instability.deathtime, male_patients_with_high_lab_instability.admission_type, male_patients_with_high_lab_instability.admit_provider_id, male_patients_with_high_lab_instability.admission_location, male_patients_with_high_lab_instability.discharge_location, male_patients_with_high_lab_instability.insurance, male_patients_with_high_lab_instability.language, male_patients_with_high_lab_instability.marital_status, male_patients_with_high_lab_instability.race, male_patients_with_high_lab_instability.dod, male_patients_with_high_lab_instability.lab_instability_score, male_controls_with_high_lab_instability.lab_instability_score AS control_lab_instability_score, (male_patients_with_high_lab_instability.lab_instability_score - male_controls_with_high_lab_instability.lab_instability_score) AS difference_in_lab_instability_score FROM male_patients_with_high_lab_instability JOIN male_controls_with_high_lab_instability ON male_patients_with_high_lab_instability.subject_id = male_controls_with_high_lab_instability.subject_id WHERE male_patients_with_high_lab_instability.lab_instability_score >= male_controls_with_high_lab_instability.lab_instability_score ORDER BY male_patients_with_high_lab_instability.lab_instability_score DESC NULLS LAST;